import React from 'react';
import { View, Text, FlatList, Image, TouchableOpacity, StyleSheet, Dimensions } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';

const { width } = Dimensions.get('window');
// Two columns with padding
const CARD_MARGIN = 10;
const CONTAINER_PADDING = 10;
const COLUMN_WIDTH = (width - (CONTAINER_PADDING * 2) - CARD_MARGIN) / 2;

interface ProductListProps {
  data: any[];
  onPress: (item: any) => void;
}

import { resolveImageUrl } from '../utils/imageUtils';

const ProductList: React.FC<ProductListProps> = ({ data, onPress }) => {
  const renderItem = ({ item }: { item: any }) => {
    // resolve image url safely
    const rawImageUrl = 
      item.primary_image || 
      item.primaryImage || 
      (item.images && item.images.length > 0 ? (item.images[0].image_url || item.images[0].imageUrl || item.images[0].url) : null) || 
      item.image;
      
    const imageUrl = resolveImageUrl(rawImageUrl);
      
    // Default rating if missing
    const rating = item.rating || 4.5;
    const reviews = item.reviews ? item.reviews.length : (item.reviewCount || 0);

    const displayPrice = item.new_price || item.newPrice || item.price;
    const displayOldPrice = item.old_price || item.oldPrice;

    return (
      <TouchableOpacity 
        style={styles.card} 
        onPress={() => onPress(item)}
        activeOpacity={0.9}
      >
        <View style={styles.imageContainer}>
             {/* Sale Badge */}
            {(item.sale || (displayOldPrice && displayPrice < displayOldPrice)) && (
                 <View style={styles.badge}>
                     <Text style={styles.badgeText}>SALE</Text>
                 </View>
            )}
            
            {/* Wishlist Icon */}
             <TouchableOpacity style={styles.wishlistIcon}>
                 <Ionicons name="heart-outline" size={18} color="#333" />
             </TouchableOpacity>

            <Image source={{ uri: imageUrl }} style={styles.image} resizeMode="cover" />
        </View>

        <View style={styles.details}>
          <Text style={styles.categoryName} numberOfLines={1}>{item.category?.name || item.category_name || 'Snacks'}</Text>
          <Text style={styles.name} numberOfLines={2}>{item.name || item.title}</Text>
          
          <View style={styles.ratingRow}>
              <View style={styles.stars}>
                {[1, 2, 3, 4, 5].map((star) => (
                  <Ionicons 
                    key={star} 
                    name={star <= Math.round(rating) ? "star" : "star-outline"} 
                    size={10} 
                    color="#FFC107" 
                  />
                ))}
              </View>
              <Text style={styles.ratingText}> ({reviews} reviews)</Text>
          </View>

          <View style={styles.priceRow}>
            <Text style={styles.price}>₹{displayPrice}</Text>
            {(displayOldPrice && displayOldPrice > displayPrice) && (
              <Text style={styles.oldPrice}>₹{displayOldPrice}</Text>
            )}
          </View>

          <View style={styles.weightContainer}>
            <Text style={styles.weightText}>{item.weight || '500g'} - ₹{displayPrice}</Text>
          </View>

          <TouchableOpacity style={styles.addButtonContainer} onPress={() => onPress(item)}>
            <LinearGradient
              colors={['#f59e0b', '#f97316']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={styles.addButton}
            >
              <Ionicons name="cart-outline" size={16} color="#fff" style={{marginRight: 4}} />
              <Text style={styles.addButtonText}>Add to cart</Text>
            </LinearGradient>
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      <FlatList
        data={data}
        renderItem={renderItem}
        keyExtractor={(item) => (item.id || Math.random()).toString()}
        numColumns={2}
        columnWrapperStyle={styles.row}
        scrollEnabled={false} 
        contentContainerStyle={{ paddingBottom: 20 }}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingHorizontal: CONTAINER_PADDING,
    marginTop: 10,
  },
  row: {
    justifyContent: 'space-between',
  },
  card: {
    width: COLUMN_WIDTH,
    backgroundColor: '#fff',
    marginBottom: 15,
    borderRadius: 12,
    // Soft shadow like Pattikadai
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.08,
    shadowRadius: 4,
    elevation: 3,
    borderWidth: 1,
    borderColor: '#f0f0f0',
    overflow: 'hidden',
  },
  imageContainer: {
    height: COLUMN_WIDTH, // Square image
    width: '100%',
    position: 'relative',
    backgroundColor: '#f9f9f9',
  },
  image: {
    width: '100%',
    height: '100%',
  },
  badge: {
    position: 'absolute',
    top: 10,
    left: 10,
    backgroundColor: '#E53935',
    paddingHorizontal: 8,
    paddingVertical: 2,
    borderRadius: 4,
    zIndex: 1,
  },
  badgeText: {
    color: '#fff',
    fontSize: 10,
    fontWeight: 'bold',
  },
  wishlistIcon: {
      position: 'absolute',
      top: 8,
      right: 8,
      width: 28,
      height: 28,
      borderRadius: 14,
      backgroundColor: '#fff',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1,
      shadowColor: "#000",
      shadowOffset: { width: 0, height: 1 },
      shadowOpacity: 0.1,
      elevation: 2,
  },
  details: {
    padding: 10,
  },
  categoryName: {
    fontSize: 10,
    color: '#888',
    marginBottom: 2,
    textTransform: 'uppercase',
  },
  name: {
    fontSize: 13,
    color: '#333',
    fontWeight: '600',
    marginBottom: 4,
    height: 36, // Fixed height for 2 lines
    lineHeight: 18,
  },
  ratingRow: {
      flexDirection: 'row',
      alignItems: 'center',
      marginBottom: 6,
  },
  stars: {
    flexDirection: 'row',
  },
  ratingText: {
      fontSize: 10,
      color: '#888',
      marginLeft: 4,
  },
  priceRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 6,
  },
  price: {
    fontSize: 14,
    fontWeight: '700',
    color: '#1a472a', // Deep green for price
    marginRight: 6,
  },
  oldPrice: {
    fontSize: 11,
    color: '#999',
    textDecorationLine: 'line-through',
  },
  weightContainer: {
    marginBottom: 8,
  },
  weightText: {
    fontSize: 11,
    color: '#666',
  },
  addButtonContainer: {
    width: '100%',
  },
  addButton: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 8,
    borderRadius: 20, // Pill shape
  },
  addButtonText: {
    color: '#fff',
    fontSize: 12,
    fontWeight: '600',
  },
});

export default ProductList;
